#nullable enable // autogenerated

using MVZ2Logic.Armors;
using MVZ2Logic.Contents.Buffs.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Games;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;


namespace MVZ2Logic.Entities
{
    public static class LogicColliderExt
    {
        public static bool IsForMain(this IEntityCollider collider)
        {
            return !NamespaceID.IsValid(collider.ArmorSlot);
        }
        public static bool IsForHelmet(this IEntityCollider collider)
        {
            return collider.ArmorSlot == LogicArmorSlots.main;
        }
        public static bool IsMainCollider(this IEntityCollider collider)
        {
            return collider.Name == EntityCollisionHelper.NAME_MAIN;
        }
    }
}
